'use strict';
const D=window.JUDO_DATA, C=window.JUDO_COURSE, V=window.JUDO_VIDEOS, R=window.JUDO_RANKS, T=window.JUDO_SPEECH, G=window.JUDO_COACH, F=window.JUDO_FLOWS, P=window.JUDO_PATH;
const KEY='judo-shodan-academy-v1'; // Preserve the original app's storage on the same website.
const fresh=()=>({lessons:{},skills:{},skillLevels:{},lessonSteps:{},reflections:{},activityLog:[],reviews:{},rankChecks:{},journal:[],exerciseLog:[],exercisePrefs:{},techLibrary:{},flowPinned:[],customFlows:[],flowHistory:[],flowPrefs:{},quizHistory:[],settings:{},profile:null,journey:'first'});
let S;try{S={...fresh(),...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{S=fresh()}
S.lessons=S.lessons&&typeof S.lessons==='object'?S.lessons:{};
S.skills=S.skills&&typeof S.skills==='object'?S.skills:{};
S.reviews=S.reviews&&typeof S.reviews==='object'?S.reviews:{};
S.rankChecks=S.rankChecks&&typeof S.rankChecks==='object'?S.rankChecks:{};
S.journal=Array.isArray(S.journal)?S.journal:[];
S.quizHistory=Array.isArray(S.quizHistory)?S.quizHistory:[];
S.skillLevels=S.skillLevels&&typeof S.skillLevels==='object'?S.skillLevels:{};
S.lessonSteps=S.lessonSteps&&typeof S.lessonSteps==='object'?S.lessonSteps:{};
S.reflections=S.reflections&&typeof S.reflections==='object'?S.reflections:{};
S.activityLog=Array.isArray(S.activityLog)?S.activityLog:[];
S.exerciseLog=Array.isArray(S.exerciseLog)?S.exerciseLog:[];
S.exercisePrefs=S.exercisePrefs&&typeof S.exercisePrefs==='object'?S.exercisePrefs:{};
S.techLibrary=S.techLibrary&&typeof S.techLibrary==='object'&&!Array.isArray(S.techLibrary)?S.techLibrary:{};
S.flowPinned=Array.isArray(S.flowPinned)?S.flowPinned:[];
S.customFlows=Array.isArray(S.customFlows)?S.customFlows:[];
S.flowHistory=Array.isArray(S.flowHistory)?S.flowHistory:[];
S.flowPrefs=S.flowPrefs&&typeof S.flowPrefs==='object'?S.flowPrefs:{};
// Adopt existing checked techniques into My Library without assuming they are favorites.
for(const [id,lev] of Object.entries(S.skillLevels))if(Number(lev)>0&&!S.techLibrary[id])S.techLibrary[id]={favorite:false,notes:'',tags:'',added:new Date().toISOString()};
const migrated=Object.keys(S.lessons).length>0||Object.keys(S.skills).length>0||S.journal.length>0||Object.keys(S.reviews).length>0;
const migratingLegacy=!S.profile&&migrated;
if(migratingLegacy){S.profile={name:'',rank:'Ikkyu',organization:'USJF',experience:'Experienced',goal:'blackbelt'};S.journey='blackbelt';}
if(migratingLegacy){try{localStorage.setItem(KEY,JSON.stringify(S))}catch(e){console.warn('Progress migration will save on the next update',e)}}
const app=document.getElementById('app');
let page=S.profile?'home':'welcome', detailId='', search='',filter='All', studyCategory='All', activeCard=null, flipped=false, quiz=null, quizScope='All', forceNew=false, lessonStep=0, audioMode=!!S.settings?.audioMode;
const h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=h;
const p=(n,total)=>total?Math.min(100,Math.round(100*n/total)):0;
const allLessons=C.lessons;
const lessonById=C.lessonById;
const allTechs=D.techniques;
const dueDate=()=>Date.now();
const yt=(term)=>V.find(term)||'https://www.youtube.com/results?search_query='+encodeURIComponent('KODOKAN '+term+' judo');
const videoLink=(name)=>V.find(name)?link(V.find(name),'▶ Watch Kodokan video'):link(yt(name),'▶ Find official demonstration');
const speechButtons=(name)=>`<div class="speech-buttons"><button class="speech" data-speak="${attr(name)}" aria-label="Hear Japanese pronunciation for ${attr(name)}">◖)) Listen</button><button class="speech subtle" data-slow="${attr(name)}" aria-label="Hear ${attr(name)} slowly">Slow</button></div>`;
let targetRank='';
let mySearch='', selectedFlowEdge='', flowMode=S.flowPrefs.mode||'combinations', flowStance=S.flowPrefs.stance||'right';
let ageGroup=S.profile?.ageGroup==='junior'?'junior':'adult';
const link=(url,label)=>`<a href="${attr(url)}" target="_blank" rel="noopener noreferrer" class="secondary linkbutton">${h(label)} <span aria-hidden="true">↗</span></a>`;
const completed=id=>!!S.lessons[id];
const journeyByKey=k=>C.routes.find(r=>r.key===k)||C.routes[0];
const learntCount=ids=>ids.filter(id=>completed(id)).length;
const chapters=C.syllabus;
function save(){try{localStorage.setItem(KEY,JSON.stringify(S))}catch{alert('Unable to save locally. Export your data from Settings.') }}
function navigate(to,id=''){page=to;detailId=id;search='';filter='All';if(to!=='review')flipped=false;if(to==='lesson')lessonStep=0;window.scrollTo({top:0,behavior:'instant'});render()}
const ranks=C.rankOptions.map(([value,label])=>`<option value="${attr(value)}">${h(label)}</option>`).join('');
function today(){let d=new Date(),offset=d.getTimezoneOffset();return new Date(d.getTime()-offset*60000).toISOString().slice(0,10)}
function highlight(id){return `<span class="flag ${completed(id)?'done':'pending'}">${completed(id)?'✓ Learned':'To learn'}</span>`}
function progressBar(n,total){return `<div class="bar" role="progressbar" aria-valuenow="${n}" aria-valuemin="0" aria-valuemax="${total}"><span style="width:${p(n,total)}%"></span></div>`}
function scopeLessonIds(key){return journeyByKey(key).lessonIds.filter(id=>lessonById[id])}
function layout(){document.querySelectorAll('nav [data-route]').forEach(b=>b.classList.toggle('active',b.dataset.route===page||(['lesson','journey'].includes(page)&&b.dataset.route==='learn')||(['library','technique','myLibrary'].includes(page)&&b.dataset.route==='myLibrary')||(['quiz','kata','settings','resources','ranks','profile','videos','review'].includes(page)&&b.dataset.route==='more')));const top=document.querySelector('.brand-sub');if(top)top.textContent=S.profile?(S.profile.rank||'Judo student')+' · Learn at your pace':'Learn judo from day one';document.body.classList.toggle('onboarding',!S.profile)}
function render(){const r={welcome,home,learn,journey,lesson,library,technique,myLibrary,flowchart,review,quiz:quizScreen,kata,resources,more,settings,profile,ranks:ranksPage,videos:videosPage};app.innerHTML=(r[page]||home)();layout()}
function welcome(){return `<section class="welcome-hero"><span class="bigkanji">柔道</span><span class="eyebrow">Your judo journey starts here</span><h1>Judo Academy</h1><p class="sub">From your first bow to advanced kata and competition. Learn Japanese terminology, explore techniques, study rank requirements, and build a personal technique library.</p><div class="hint">Anyone can begin at white belt. If you've already trained, choose your current level instead.</div></section><form id="profileForm" class="panel"><h2>Create your learning profile</h2><label>What should the app call you? <span class="muted">(optional)</span><input name="name" class="field" maxlength="60" placeholder="Your name or nickname" autocomplete="off"></label><label>Your current belt / grade<select class="field" name="rank">${ranks}</select></label><label>Affiliation or rank system<select class="field" name="organization"><option value="Not sure">Not sure yet</option><option value="USJF">USJF</option><option value="USA Judo">USA Judo</option><option value="USJA">USJA</option><option value="Kodokan">Kodokan</option><option value="Other / local dojo">Other / local dojo</option></select></label><label>What interests you most?<select class="field" name="goal"><option value="first">Starting judo</option><option value="fundamentals">Improving fundamentals</option><option value="blackbelt">Working toward black belt</option><option value="sport">Competing</option><option value="heritage">Kata, history, and teaching</option></select></label><p class="small muted">No account needed. This information is stored only in this browser unless you export a backup.</p><button class="primary full" type="submit">Enter the dojo →</button></form>`}
const skillLevel=id=>Number(S.skillLevels[id]??(S.skills[id]?1:0))||0;
const stageLabels=['Not started','Introduced','Understood','Demonstrated','Applied in randori'];
function markActivity(kind,detail=''){S.activityLog.unshift({when:new Date().toISOString(),kind,detail});S.activityLog=S.activityLog.slice(0,1500)}
function lessonChecklist(id){const a=S.lessonSteps[id];return Array.isArray(a)?a:[false,false,false,false]}

function rankChoices(selected,org){return P.options(selected,org,ageGroup).map(x=>`<option value="${attr(x.value)}" ${P.canonical(selected)===x.value?'selected':''}>${h(x.label)}</option>`).join('')}
function rankItems(grade){const org=S.profile?.organization||'Not sure',age=ageGroup,items=P.items(org,grade,age);const key=[org,age,grade].join('|');const checked=S.rankChecks[key]||{};return {items,checked,key,done:items.filter((x,i)=>checked[String(i)]).length}}
function rankPanel(grade,caption,tone){const info=rankItems(grade);return `<section class="panel simple-rank-card ${tone}"><div class="row between"><div><span class="eyebrow">${h(caption)}</span><h2>${h(P.named[grade]||grade)}</h2></div><span class="rank-fraction">${info.done}/${info.items.length}</span></div>${progressBar(info.done,info.items.length)}<div class="rank-check-items">${info.items.map(([name,source],i)=>`<label class="home-rank-check"><input type="checkbox" data-home-rank="${attr(grade)}" data-home-rank-index="${i}" ${info.checked[String(i)]?'checked':''}><span><strong>${h(name)}</strong><small>${h(source)}</small></span></label>`).join('')}</div></section>`}
function home(){if(!S.profile)return welcome();const current=P.canonical(S.profile.rank||'White belt');const target=P.validTarget(current,S.profile.targetRank)?P.canonical(S.profile.targetRank):P.defaults(current,S.profile.organization);const org=S.profile.organization||'Not sure';const previous=P.previous(current,org);const guide=R.guides[org]||R.guides['Not sure'];return `<section class="rank-home-top"><span class="eyebrow">YOUR JUDO JOURNEY</span><h1>Rank progression</h1><p class="sub">Choose where you are and what you are working toward. Check off study topics as you learn them.</p><div class="rank-pickers"><label>Current rank<select class="field" id="homeCurrentRank">${rankChoices(current,org)}</select></label><label>Studying for<select class="field" id="homeTargetRank">${P.options(target,org,ageGroup).filter(o=>P.validTarget(current,o.value)).map(o=>`<option value="${attr(o.value)}" ${target===o.value?'selected':''}>${h(o.label)}</option>`).join('')||`<option value="${attr(target)}">${h(P.named[target]||target)}</option>`}</select></label></div><div class="rank-affiliation">${h(org)} · ${ageGroup==='junior'?'Junior':'Adult'} <button class="ghost small" data-go="profile">Change organization →</button></div></section><div class="rank-home-checklists">${rankPanel(target,'YOUR GOAL · PREPARE','next')}<details class="rank-review-toggle"><summary><strong>${previous?'Review previous grade: '+h(P.named[previous]||previous):'Review white belt foundations'}</strong><span>Show checklist ▾</span></summary>${previous?rankPanel(previous,'PREVIOUS GRADE · REVIEW','previous'):rankPanel('White belt','START HERE · FOUNDATIONS','previous')}</details></div><div class="rank-help"><strong>These are study checklists, not promotion approvals.</strong><p>${h(guide.note)} ${target==='Shodan'&&org==='USJF'?'Shodan checklist items are drawn from the 2021 USJF senior recommendations; verify current Yudanshakai rules.':'Most items are suggested learning milestones. Confirm exact requirements with your instructor.'}</p>${guide.url?link(guide.url,'View organization guidance'):''}</div><div class="rank-quick-access"><button data-go="learn"><span>▤</span><strong>Study lessons</strong><small>Structured learning</small></button><button data-go="myLibrary"><span>技</span><strong>My Library</strong><small>Pin techniques</small></button><button data-go="flowchart"><span>↗</span><strong>Flowchart</strong><small>Build combinations</small></button></div>`}

function learn(){return `<span class="eyebrow">Explore the curriculum</span><h1>Choose your path</h1><p class="sub">Start anywhere, or follow a structured journey. Beginners should begin with <strong>My first month</strong>; experienced judoka can move directly to the material they need.</p><div class="journeygrid">${C.routes.map(r=>{const ids=scopeLessonIds(r.key),count=learntCount(ids);return `<button class="journey-card" data-go="journey" data-id="${r.key}"><div class="row between"><span class="journey-mark">${r.key==='first'?'壱':r.key==='blackbelt'?'黒':r.key==='sport'?'勝':r.key==='heritage'?'道':'技'}</span><span class="small muted">${count}/${ids.length}</span></div><h2>${h(r.title)}</h2><p>${h(r.subtitle)}</p>${progressBar(count,ids.length)}</button>`}).join('')}</div><h2>Browse by subject</h2><div class="subjectgrid">${chapters.map(s=>`<button class="subject-pill ${s.tone}" data-browse="${s.key}"><span>${s.icon}</span><strong>${h(s.label)}</strong><small>${h(s.subtitle)}</small></button>`).join('')}</div><div class="panel"><strong>How belt progression works</strong><p class="small muted">Belt colors and kyu grades differ between adult, junior and national programs. This app uses learning stages for convenience and never promotes you automatically. Choose your actual rank in Settings and check grading requirements with your instructor.</p></div>`}
function journey(){const r=journeyByKey(detailId),ids=scopeLessonIds(r.key),done=learntCount(ids);S.journey=r.key;save();return `<button class="ghost" data-go="learn">← All learning paths</button><span class="eyebrow">Learning pathway</span><h1>${h(r.title)}</h1><p class="sub">${h(r.subtitle)}</p><div class="panel"><div class="row between"><strong>${done} of ${ids.length} lessons completed</strong><span>${p(done,ids.length)}%</span></div>${progressBar(done,ids.length)}<p class="small muted">Tap a lesson to view explanations, videos, practice prompts and a self-check.</p></div>${ids.map((id,i)=>{const l=lessonById[id];return `<div class="lesson-row"><button data-go="lesson" data-id="${attr(id)}" class="lesson-click"><span class="ordinal">${i+1}</span><span><strong>${h(l.title)}</strong><small>${h(l.goal)}</small></span></button><label title="Mark as studied"><input type="checkbox" data-lesson="${attr(id)}" ${completed(id)?'checked':''} aria-label="Completed ${attr(l.title)}"></label></div>`}).join('')}`}
function legacyContent(l){let a=[],drills=[],question=[];let n=l.oldNumber;
if(n<=5){a=['Learn the Japanese term, its English meaning, and what it changes about your movement.','Watch a skilled demonstration from the Kodokan or your instructor.','Explain it without relying on BJJ terminology, then use it in cooperative practice.'];drills=['Repeat the term aloud and explain it to a partner.','Record one correction your instructor gave you.'];}
else if(n===6){a=['Kodokan standing throwing techniques are grouped into te, koshi, ashi, ma sutemi and yoko sutemi waza.','Learn the category using representative techniques rather than literal translation alone.'];}
else if(n>=7&&n<=11){let g=D.groups[n-7];a=['Know the name, translation and Kodokan classification of every technique listed below.','For each, identify safe grips, movement, kuzushi, tsukuri and kake under coaching.','Compare the cooperative form with what changes under controlled resistance.'];drills=['Choose two techniques for coach-supervised uchikomi.','Discuss timing, grips or footwork mistakes with your instructor.'];}
else if(n===13){a=['Osaekomi waza are formal hold-down techniques. Study positioning, control, transitions and escapes.','Pinning should be controlled; release promptly for taps and commands.'];}
else if(n===15||n===16){a=['Learn the Kodokan terminology and recognize the positions before attempting application.','Choking and joint locking techniques require qualified supervision, age-appropriate rules, and immediate release on a tap.','Practice entries, defensive recognition and control rather than trying to force a finish.'];}
else if(n>=23&&n<=27){a=['Study the correct sequence, etiquette, attack, defensive response, timing and partner roles.','Formal kata requires precision as well as safe execution. A qualified kata instructor is essential.'];drills=['Watch one set in its full sequence.','Explain the role of tori and uke before practicing at reduced speed.'];}
else if(n===28){a=['Understand Jigoro Kano’s educational aims and the founding of Kodokan in 1882.','Relate seiryoku zenyo and jita kyoei to daily dojo practice.'];}
else if(n===29){a=['Recognize common referee commands and signals.','Current rules may change by event, federation or age group; always verify the latest event rulebook.'];}
else{a=['Know the core Japanese vocabulary, physical principles and safety considerations.','Explain the technique or concept, then demonstrate with a qualified instructor.','Be able to describe when it does and does not apply during randori.'];}
return {a,drills,question};}
function lesson(){const l=lessonById[detailId];if(!l)return '<h1>Lesson not found</h1>';let content=l.explain.length?{a:l.explain,drills:l.practice,question:l.reflect}:legacyContent(l);let names=[];
if(l.oldNumber>=7&&l.oldNumber<=11)names=D.groups[l.oldNumber-7].map(t=>({name:t[0],detail:t[1]+' · '+t[2]+' waza'}));
else if(l.oldNumber===13)names=allTechs.filter(t=>t.category==='Osaekomi waza').map(t=>({name:t.name,detail:t.meaning}));
else if(l.oldNumber===15)names=allTechs.filter(t=>t.category==='Shime waza').map(t=>({name:t.name,detail:t.meaning}));
else if(l.oldNumber===16)names=allTechs.filter(t=>t.category==='Kansetsu waza').map(t=>({name:t.name,detail:t.meaning}));
else if(l.oldNumber>=23&&l.oldNumber<=27)names=D.kata[l.oldNumber-23].slice(1).map(name=>({name,detail:'Nage no Kata'}));
else if(l.oldNumber===12)names=allTechs.filter(t=>t.section==='Nage waza'&&!t.set).map(t=>({name:t.name,detail:t.meaning}));
const source= l.search&&Array.isArray(l.search)?l.search[0]:l.search||l.title;
const steps=lessonChecklist(l.id), titles=['Learn','Watch','Practice','Reflect'],step=lessonStep;const cards=[`<div class="panel lesson-content"><h2>Understand the idea</h2>${content.a.map(x=>`<p>${h(x)}</p>`).join('')}${names.length?`<h3>Techniques featured</h3>${names.slice(0,12).map(t=>{const found=allTechs.find(x=>x.name===t.name);return `<div class="techrow"><div><strong>${h(t.name)}</strong><small>${h(t.detail)}</small></div>${found?`<button class="chip" data-go="technique" data-id="${attr(found.id)}">Explore →</button>`:videoLink(t.name)}</div>`}).join('')}`:''}</div>`,`<div class="panel lesson-content"><h2>Watch with purpose</h2><p>Notice posture, distance, timing and how uke lands. Pause the video before the finish and predict what happens next.</p><div class="actions">${videoLink(source)}${link('https://kdkjd.org/names-of-judo-techniques/','Kodokan technique directory')}</div><div class="watch-prompts"><strong>While watching, look for:</strong><ul><li>Where does uke’s balance begin to change?</li><li>What position does tori establish first?</li><li>How is uke kept safe?</li></ul></div><p class="tiny muted">Videos and external websites require internet access.</p></div>`,`<div class="panel lesson-content"><h2>Take it to the tatami</h2><ol class="readable-list">${(content.drills.length?content.drills:['Explain the Japanese term to a partner.','Perform coach-approved cooperative drills before resistance.','Remember one correction from your instructor.']).map(s=>`<li>${h(s)}</li>`).join('')}</ol><p class="safety"><strong>Train with supervision:</strong> Videos do not replace qualified instruction. Never practice throws, chokes or joint locks beyond your level.</p><button class="secondary" data-go="myLibrary">Browse technique library →</button></div>`,`<div class="panel lesson-content"><h2>Teach it back</h2><p>${h(content.question[0]||`What is the most important thing you learned about ${l.title}?`)}</p><label>My own explanation<textarea class="field" id="lessonReflection" rows="5" maxlength="1500" placeholder="Explain it in your own words…">${h(S.reflections[l.id]||'')}</textarea></label><button class="secondary" data-save-reflection="${attr(l.id)}">Save reflection</button><details><summary>What should a good answer include?</summary><p class="muted small">Describe the Japanese terms, purpose, safe partner interaction and one thing your coach should verify.</p></details><button class="secondary" data-go="quiz">Knowledge quiz →</button></div>`];return `<button class="ghost" data-go="journey" data-id="${attr(S.journey)}">← Learning path</button><span class="eyebrow">${h(l.path==='shodan'?'Black belt study':chapters.find(x=>x.key===l.path)?.label||'Judo lesson')} · ${h(l.level)}</span><h1>${h(l.title)}</h1><p class="lead">${h(l.goal)}</p><div class="lesson-steps">${titles.map((t,i)=>`<button class="lesson-step ${step===i?'selected':''} ${steps[i]?'finished':''}" data-lesson-tab="${i}" aria-current="${step===i?'step':'false'}"><span>${steps[i]?'✓':i+1}</span><small>${t}</small></button>`).join('')}</div>${cards[step]}<div class="panel guided-next"><span class="small muted">Step ${step+1} of 4 · ${steps.filter(Boolean).length} reviewed</span><div class="actions">${step>0?`<button class="secondary" data-lesson-back>← Previous</button>`:''}<button class="primary" data-lesson-continue="${attr(l.id)}">${step===3?'Finish lesson':'Mark step reviewed →'}</button></div></div><div class="panel"><label class="row"><input type="checkbox" data-lesson="${attr(l.id)}" ${completed(l.id)?'checked':''}><strong>I have studied and practiced this lesson</strong></label><p class="small muted">Self-assessment only. Ask your instructor to verify physical technique quality.</p></div>`}
function library(){return `${exploreNav('library')}<span class="eyebrow">Technique encyclopedia</span><h1>Explore techniques</h1><p class="sub">${allTechs.filter(t=>t.official).length} official Kodokan techniques plus ${allTechs.filter(t=>!t.official).length} additional variations. Browse throws, holds, strangles and joint locks.</p><input class="field search" type="search" id="techSearch" placeholder="Search Japanese or English names…" value="${attr(search)}" aria-label="Search techniques"><div class="filters">${['All','Gokyo','Te waza','Koshi waza','Ashi waza','Ma sutemi waza','Yoko sutemi waza','Osaekomi waza','Shime waza','Kansetsu waza'].map(cat=>`<button class="chip ${filter===cat?'active':''}" data-filter="${cat}">${cat}</button>`).join('')}</div><div id="techResults">${renderTechs()}</div><p class="note small">Some historically recognized techniques are prohibited under modern competition rules. See the current federation rulebook before shiai.</p>`}
function renderTechs(){let q=search.trim().toLowerCase(),items=allTechs.filter(t=>(filter==='All'||filter==='Gokyo'&&t.set>0||t.category===filter)&&[t.name,t.meaning,t.category].some(s=>s.toLowerCase().includes(q)));return `<p class="small muted">Showing ${items.length} results · ${Object.keys(G.guides).length} detailed technique study guides</p>${items.map(t=>`<div class="techrow"><button class="techclick" data-go="technique" data-id="${t.id}"><strong>${h(t.name)}</strong><small>${h(t.meaning)} · ${h(t.category)}${t.set?' · Gokyo '+t.set:''}${G.guides[t.id]?' · ★ Study guide':''}</small></button><button class="lib-quick-add ${S.techLibrary[t.id]?'saved':''}" data-library-add="${t.id}" aria-label="${S.techLibrary[t.id]?'Remove ' : 'Save '}${attr(t.name)} ${S.techLibrary[t.id]?'from':'to'} My Library">${S.techLibrary[t.id]?'✓':'+'}</button><button class="level-token" data-go="technique" data-id="${t.id}" aria-label="Technique progress: ${h(stageLabels[skillLevel(t.id)])}">${skillLevel(t.id)?'L'+skillLevel(t.id):'›'}</button></div>`).join('')||'<div class="panel">No matching techniques. Try a different name or category.</div>'}`}
function techniqueBase(){const t=allTechs.find(x=>x.id===detailId);if(!t)return '<h1>Technique not found</h1>';const g=G.guides[t.id],level=skillLevel(t.id),related=(g?.links||[]).map(name=>allTechs.find(x=>x.name===name)).filter(Boolean);const general=t.section==='Nage waza'?['Kuzushi: identify the direction and timing of the off balance.','Tsukuri: find the correct foot placement, grip and posture.','Kake: observe how the throw finishes with uke under control.']:t.category==='Osaekomi waza'?['Recognize the controlled position and how weight is distributed.','Practice coach-approved transitions and escapes at low resistance.','Release immediately for a stop or partner request.']:['Recognize the formal position and competition restrictions.','Practice only with qualified supervision and appropriate eligibility.','Release immediately for a tap or verbal stop.'];return `<button class="ghost" data-go="myLibrary">← My Library</button><div class="eyebrow">${h(t.section)} · ${h(t.category)}${g?' · IN-DEPTH GUIDE':''}</div><h1>${h(t.name)}</h1><p class="lead">${h(t.meaning)}</p><div class="phonetics"><span class="kana">${h(T.kana(t.name))}</span>${speechButtons(t.name)}</div><section class="tech-video"><div class="video-badge">▶ KODOKAN REFERENCE</div><h2>Watch the demonstration</h2><p>Watch slowly and look for posture, timing, safe partner control and the direction of movement.</p>${videoLink(t.name)}<small>Official video opens on YouTube. Requires internet.</small></section>${g?`<div class="panel technique-guide"><span class="eyebrow">THE CENTRAL IDEA</span><p class="lead">${h(g.idea)}</p><div class="coach-points">${[['Kuzushi / control',g.kuzushi],['Tsukuri / position',g.entry],['Kake / finish',g.finish]].map(([name,value],i)=>`<div class="coach-point"><span>${i+1}</span><div><strong>${h(name)}</strong><p>${h(value)}</p></div></div>`).join('')}</div></div><div class="panel"><h2>Common mistakes to recognize</h2><ul class="readable-list">${g.errors.map(x=>`<li>${h(x)}</li>`).join('')}</ul></div><div class="panel"><h2>Coach-approved mat assignment</h2><p>${h(g.drill)}</p></div>${related.length?`<div class="panel"><h2>Related techniques</h2>${related.map(x=>`<button class="more-row" data-go="technique" data-id="${attr(x.id)}"><strong>${h(x.name)}</strong><small>${h(x.meaning)}</small><span>›</span></button>`).join('')}</div>`:''}`:`<div class="panel"><h2>Study checklist</h2><p class="small muted">This technique currently has a reference checklist rather than a full written coaching guide.</p><ul class="readable-list">${general.map(x=>`<li>${h(x)}</li>`).join('')}</ul></div>`}<div class="panel skill-stage"><span class="eyebrow">PERSONAL DEVELOPMENT</span><h2>How well do you know this?</h2><p class="small muted">Choose the highest level you can support with your own training. These are self-reported milestones, not belt exam sign-offs.</p><div class="stage-options">${stageLabels.map((x,i)=>`<button class="stage-choice ${level===i?'chosen':''}" data-level="${i}" data-tech="${attr(t.id)}" aria-pressed="${level===i}"><span>${level===i?'●':'○'}</span><strong>${h(x)}</strong></button>`).join('')}</div></div><div class="panel safety"><strong>Partner safety</strong><p>Use formal coaching for physical practice. Kodokan classification does not mean a technique is legal for your competition division.</p></div>`}

// Saved individual techniques are different from learned/proficiency ratings.
const inMyLibrary=id=>!!S.techLibrary[id];
const favorite=id=>!!S.techLibrary[id]?.favorite;
function libraryOrder(){return allTechs.filter(t=>inMyLibrary(t.id)).sort((a,b)=>Number(favorite(b.id))-Number(favorite(a.id))||a.name.localeCompare(b.name))}
function saveToLibrary(id){if(!allTechs.some(t=>t.id===id))return;if(inMyLibrary(id)){delete S.techLibrary[id];}else{S.techLibrary[id]={favorite:false,notes:'',tags:'',added:new Date().toISOString()};}save();render();}
function toggleFavorite(id){if(!allTechs.some(t=>t.id===id))return;const item=S.techLibrary[id]||(S.techLibrary[id]={favorite:false,notes:'',tags:'',added:new Date().toISOString()});item.favorite=!item.favorite;save();render();}
function exploreNav(active){return `<div class="academy-explore-nav library-tabs"><button class="${active==='myLibrary'?'active':''}" data-go="myLibrary">My Library</button><button class="${active==='library'?'active':''}" data-go="library">Explore techniques</button></div>`}
function myLibrary(){const entries=libraryOrder(),stars=entries.filter(t=>favorite(t.id));return `${exploreNav('myLibrary')}<section class="my-library-hero"><span class="eyebrow">YOUR TECHNIQUES</span><h1>My Library</h1><p class="sub">Save techniques you want to study. Tap ★ to pin your favorites to the top.</p><div class="my-library-stats"><span><strong>${entries.length}</strong><small>Saved</small></span><span><strong>${stars.length}</strong><small>Pinned</small></span></div><button class="primary" data-go="library">+ Explore techniques</button></section><label class="flow-search-label">Search saved techniques<input class="field" type="search" id="myTechSearch" value="${attr(mySearch)}" placeholder="Technique, category, or note…"></label><div id="myLibraryResults">${myLibraryResults()}</div>${entries.length?`<button class="secondary full" data-go="flowchart">Build combinations from your library →</button>`:''}`}

function myLibraryResults(){const query=mySearch.trim().toLowerCase(),items=libraryOrder().filter(t=>[t.name,t.meaning,t.category,S.techLibrary[t.id]?.notes,S.techLibrary[t.id]?.tags].some(x=>String(x||'').toLowerCase().includes(query)));if(!items.length)return `<div class="panel flow-empty"><strong>${query?'No matching techniques':'Your library is empty'}</strong><p>${query?'Try a different search.':'Start with your best throws. Save O soto gari, O uchi gari or Tai otoshi, and the flowchart will suggest combinations.'}</p><button class="secondary" data-go="library">Browse techniques →</button></div>`;return items.map(t=>`<div class="flow-library-row"><button class="flow-fav ${favorite(t.id)?'is-favorite':''}" data-library-star="${t.id}" title="Favorite" aria-label="${favorite(t.id)?'Unfavorite':'Favorite'} ${attr(t.name)}" aria-pressed="${favorite(t.id)}">${favorite(t.id)?'★':'☆'}</button><button class="flow-library-name" data-go="technique" data-id="${t.id}"><strong>${h(t.name)}</strong><small>${h(t.meaning)} · ${h(t.category)}</small>${S.techLibrary[t.id].tags?`<em>${h(S.techLibrary[t.id].tags)}</em>`:''}</button><button class="lib-quick-add saved" data-library-add="${t.id}" aria-label="Remove ${attr(t.name)} from My Library">✓</button></div>`).join('')}
function technique(){const t=allTechs.find(x=>x.id===detailId);if(!t)return techniqueBase();const entry=S.techLibrary[t.id],count=F.edges.filter(e=>e.from===t.name).length;return `${exploreNav('myLibrary')}<section class="panel technique-personal"><div class="row between"><span class="eyebrow">YOUR TECHNIQUE LIBRARY</span><span class="tiny muted">${h(stageLabels[skillLevel(t.id)])}</span></div><div class="flow-tech-actions"><button class="${entry?'secondary':'primary'}" data-library-add="${t.id}">${entry?'✓ Saved · Remove':'＋ Save to My Library'}</button><button class="secondary ${entry?.favorite?'flow-star-selected':''}" data-library-star="${t.id}" aria-pressed="${!!entry?.favorite}">${entry?.favorite?'★ Favorite':'☆ Make favorite'}</button></div>${entry?`<form id="techNotesForm" data-id="${t.id}"><label>My notes<textarea class="field" name="notes" maxlength="2200" rows="3" placeholder="Grips, footwork, coach feedback…">${h(entry.notes||'')}</textarea></label><label>Tags (comma separated)<input class="field" name="tags" value="${attr(entry.tags||'')}" maxlength="160" placeholder="Tokui waza, left side, needs work"></label><button type="submit" class="secondary">Save notes</button></form>`:''}${count?`<button class="flow-tech-link" data-go="flowchart" data-id="${t.id}">Explore ${count} linked techniques →</button>`:''}</section>${techniqueBase()}`}
const flowEdgeById=id=>[...F.edges,...S.customFlows].find(e=>e.id===id);
const flowType=e=>e.kind||'Combination';
const flowEdges=()=>[...F.edges,...S.customFlows.filter(e=>e&&allTechs.some(t=>t.name===e.from)&&allTechs.some(t=>t.name===e.to))];
const flowRoot=()=>{const roots=[...new Set(flowEdges().map(e=>e.from))];const pref=S.flowPrefs.root;return roots.includes(pref)?pref:(libraryOrder().find(t=>roots.includes(t.name)&&favorite(t.id))||libraryOrder().find(t=>roots.includes(t.name)))?.name||'O uchi gari'};
const techByName=name=>allTechs.find(t=>t.name===name);
const flowScore=e=>{const a=techByName(e.from),b=techByName(e.to);return Number(S.flowPinned.includes(e.id))*20+Number(e.personal)*10+Number(favorite(a?.id))*7+Number(favorite(b?.id))*6+Number(inMyLibrary(b?.id))*3+Number(inMyLibrary(a?.id))*2+Math.min(4,skillLevel(b?.id))};
function filterFlow(e){return flowMode==='all'||(flowMode==='pinned'?(S.flowPinned.includes(e.id)||e.personal):flowMode==='combinations'?e.kind==='Combination':flowMode==='counters'?e.kind==='Counter':flowMode==='ground'?e.kind==='Ground transition':false)}
function suggestionsForRoot(root){return flowEdges().filter(e=>e.from===root&&filterFlow(e)).sort((a,b)=>flowScore(b)-flowScore(a)||a.id.localeCompare(b.id))}
const flowSource=e=>F.sources[e.source]||null;
function flowText(value){let text=String(value||'');if(flowStance==='left')text=text.replace(/\b(right|left)\b/gi,x=>x.toLowerCase()==='right'?'__LEFT__':'right').replace(/__LEFT__/g,'left');return text;}
function flowSelectionFor(root){const first=suggestionsForRoot(root).slice(0,4);const second=[];for(const f of first){if(!['combinations','all'].includes(flowMode)||f.kind!=='Combination')continue;const next=flowEdges().filter(e=>e.from===f.to&&e.id!==f.id&&e.kind==='Combination'&&e.to!==root).sort((a,b)=>flowScore(b)-flowScore(a));for(const n of next.slice(0,1)){if(!second.some(x=>x.id===n.id))second.push(n);}}return {first,second:second.slice(0,4)}}
function flowMap(root){const {first,second}=flowSelectionFor(root);const L0=[root],L1=[...new Set(first.map(e=>e.to))],L2=[...new Set(second.map(e=>e.to))];let height=Math.max(270,Math.max(L1.length,L2.length)*82+68);const coordinates=new Map();for(const [k,ls] of [L0,L1,L2].entries()){ls.forEach((n,i)=>coordinates.set(`${k}|${n}`,{x:135+k*275,y:(height-(ls.length-1)*82)/2+i*82}));}const svgNodes=[...L0.map(x=>({name:x,layer:0})),...L1.map(x=>({name:x,layer:1})),...L2.map(x=>({name:x,layer:2}))];const edges=[...first.map(e=>({...e,fromLayer:0,toLayer:1})),...second.map(e=>({...e,fromLayer:1,toLayer:2}))];return `<div class="flow-chart-scroller" role="region" tabindex="0" aria-label="Technique combination flow diagram. Swipe to pan."><svg class="flow-svg" viewBox="0 0 850 ${height}" width="850" height="${height}" role="img" aria-label="${attr(root)} has ${first.length} first responses and ${second.length} follow-up possibilities"><defs><marker id="flow-arrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M 0 0 L 6 3 L 0 6 Z" fill="#6d9bc7"/></marker></defs>${edges.map(e=>{const a=coordinates.get(`${e.fromLayer}|${e.from}`),b=coordinates.get(`${e.toLayer}|${e.to}`);if(!a||!b)return '';const d=`M ${a.x+81} ${a.y} C ${a.x+140} ${a.y}, ${b.x-140} ${b.y}, ${b.x-83} ${b.y}`;return `<g data-flow-edge="${attr(e.id)}" tabindex="0" role="button" aria-label="Inspect ${attr(e.from)} to ${attr(e.to)}"><title>${h(e.from)} → ${h(e.to)}</title><path d="${d}" fill="none" stroke="#6d9bc7" stroke-width="2.5" marker-end="url(#flow-arrow)"/><path d="${d}" fill="none" stroke="transparent" stroke-width="22" class="flow-edge-hit"/></g>`}).join('')}${svgNodes.map(n=>{const c=coordinates.get(`${n.layer}|${n.name}`),t=techByName(n.name);return `<g class="flow-svg-node ${n.layer===0?'root':''} ${inMyLibrary(t?.id)?'owned':''}" data-flow-node="${attr(n.name)}" tabindex="0" role="button" aria-label="Focus on ${attr(n.name)}"><rect x="${c.x-83}" y="${c.y-26}" width="166" height="52" rx="14"/><text text-anchor="middle" x="${c.x}" y="${c.y-3}" class="node-title">${h(n.name.length>19?n.name.slice(0,17)+'…':n.name)}</text><text text-anchor="middle" x="${c.x}" y="${c.y+14}" class="node-subtitle">${n.layer===0?'START':inMyLibrary(t?.id)?'In My Library':'Suggested'}</text></g>`}).join('')}</svg></div><p class="tiny muted">Swipe the chart horizontally. Tap a connection or a technique to inspect it. Colors indicate saved techniques, not success probability.</p>`}
function flowCard(e){const source=flowSource(e),pinned=S.flowPinned.includes(e.id),count=S.flowHistory.filter(x=>x.id===e.id).length;return `<article class="flow-connection"><div class="row between"><span class="flow-kind">${h(e.kind)}${e.personal?' · Yours':''}</span></div><button class="flow-connection-title" data-flow-edge="${attr(e.id)}"><strong>${h(e.from)}</strong><span aria-hidden="true">→</span><strong>${h(e.to)}</strong></button><p class="small">${h(e.reaction)}</p><div class="flow-connection-actions"><button class="secondary" data-flow-edge="${attr(e.id)}">View steps →</button><button class="ghost ${pinned?'is-pinned':''}" data-flow-pin="${attr(e.id)}">${pinned?'★ Saved':'☆ Save'}</button>${e.personal?`<button class="ghost danger-text" data-flow-remove="${attr(e.id)}">Delete</button>`:''}</div>${source?`<small class="muted">${e.kind==='Counter'?'Technique reference':'Example from'}: ${h(source.name.split(',')[0])}. Footwork cues are educational interpretation.</small>`:''}</article>`}
function flowDetail(e){if(!e)return '';const source=flowSource(e),a=techByName(e.from),b=techByName(e.to),count=S.flowHistory.filter(x=>x.id===e.id).length;return `<section class="flow-details panel"><span class="eyebrow">${h(e.kind.toUpperCase())} · ${h(e.level||'Your practice')}</span><h2>${h(e.from)} <span aria-hidden="true">→</span> ${h(e.to)}</h2><p class="flow-default-assumption">Cues are based on conventional sleeve/lapel grips. ${flowStance==='left'?'Directional words are mirrored for left-handed study; have a coach verify the positions.':'Footwork examples assume a right-handed stance.'} Actual grips and stance may require coaching adjustments.</p><ol class="flow-steps"><li><strong>1. Read uke’s reaction</strong><p>${h(flowText(e.reaction))}</p></li><li><strong>2. Hand placement and grips</strong><p>${h(flowText(e.hands))}</p></li><li><strong>3. Foot placement and entry</strong><p>${h(flowText(e.feet))}</p></li><li><strong>4. Link the technique</strong><p>${h(flowText(e.finish))}</p></li><li><strong>5. Drill on the mat</strong><p>${h(flowText(e.drill))}</p></li></ol><div class="flow-video-links">${a&&V.find(a.name)?link(V.find(a.name),'▶ Watch '+a.name):''}${b&&V.find(b.name)?link(V.find(b.name),'▶ Watch '+b.name):''}</div><div class="flow-detail-actions">${b&&!inMyLibrary(b.id)?`<button class="secondary" data-library-add="${attr(b.id)}">+ Add ${h(b.name)}</button>`:''}${a&&!inMyLibrary(a.id)?`<button class="secondary" data-library-add="${attr(a.id)}">+ Save starting throw</button>`:''}</div>${source?`<p class="flow-source"><strong>Reference:</strong> <a href="${attr(source.url)}" target="_blank" rel="noopener noreferrer">${h(source.name)} ↗</a></p>`:`<p class="flow-source">${e.personal?'Personal connection. Your notes have not been independently verified.':'Educational coaching suggestion without a specific technique pairing citation.'}</p>`}<p class="small muted">Practice under a qualified instructor; keep the partner safe and review competition legality for the age group. Suggested transitions are not guaranteed to work in randori.</p></section>`}
function flowchart(){const libs=libraryOrder(),roots=[...new Set([...libs.map(x=>x.name),...flowEdges().map(x=>x.from)])].filter(n=>!!techByName(n));const root=detailId&&techByNameId(detailId)?.name||flowRoot();const arr=suggestionsForRoot(root),allCandidate=[...arr,...flowSelectionFor(root).second],selected=allCandidate.find(e=>e.id===selectedFlowEdge)||arr[0];return `<section class="flow-hero"><span class="eyebrow">TACTICAL JUDO</span><h1>Combination Flowchart</h1><p class="sub">Build and edit combinations with precise reactions, grips, footwork and finishes.</p><div class="flow-hero-actions"><button class="primary" data-open-builder>＋ Build a combination</button><button class="secondary" data-go="myLibrary">My Library</button></div><div class="flow-metrics"><span><strong>${libs.length}</strong><small>My Library</small></span><span><strong>${libs.filter(t=>favorite(t.id)).length}</strong><small>Favorite throws</small></span><span><strong>${S.flowPinned.length}</strong><small>Saved routes</small></span></div></section><div class="panel flow-control-panel"><label>Start with<select class="field" id="flowRoot">${roots.map(n=>`<option value="${attr(n)}" ${n===root?'selected':''}>${h(n)}${favorite(techByName(n)?.id)?' ★':''}</option>`).join('')}</select></label><div class="flow-control-grid"><label>Show<select class="field" id="flowMode">${[['combinations','Combinations'],['counters','Counters'],['ground','Ground transitions'],['pinned','My saved routes'],['all','All connections']].map(([v,l])=>`<option value="${v}" ${flowMode===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Stance<select class="field" id="flowStance"><option value="right" ${flowStance==='right'?'selected':''}>Right-handed cues</option><option value="left" ${flowStance==='left'?'selected':''}>Left-handed cues</option></select></label></div><p class="tiny muted">Recommendations prioritize saved favorites. They are curated examples, not a statistically measured ranking of the most commonly used combinations.</p></div>${libs.some(t=>favorite(t.id)&&flowEdges().some(e=>e.from===t.name))?`<div class="flow-favorites"><span class="eyebrow">START FROM A FAVORITE</span><div class="flow-fav-pills">${libs.filter(t=>favorite(t.id)&&flowEdges().some(e=>e.from===t.name)).map(t=>`<button class="${root===t.name?'active':''}" data-flow-root="${attr(t.name)}">★ ${h(t.name)}</button>`).join('')}</div></div>`:''}${arr.length?`<div class="section-heading"><h2>Visual pathways</h2><span class="tiny muted">${arr.length} connections</span></div>${flowMap(root)}<div class="section-heading"><h2>Suggested links</h2></div><div class="flow-connections">${arr.map(flowCard).join('')}</div>${flowDetail(selected)}`:`<div class="panel flow-empty"><strong>No ${flowMode==='pinned'?'saved routes':'curated '+flowMode} from ${h(root)} yet.</strong><p>Try All connections, choose another throw, or build your own route below.</p></div>`}<details class="panel flow-custom" id="customFlowBuilder"><summary><strong>＋ Build my own connection</strong><small>Link two techniques and record what your instructor taught you.</small></summary><form id="customFlowForm"><label>First technique<select name="from" class="field" required>${libs.map(t=>`<option ${t.name===root?'selected':''} value="${attr(t.name)}">${h(t.name)}</option>`).join('')}</select></label><label>Next technique<select name="to" class="field" required>${libs.map(t=>`<option value="${attr(t.name)}">${h(t.name)}</option>`).join('')}</select></label><label>What does uke do?<textarea name="reaction" class="field" required maxlength="420" placeholder="Uke steps backward to recover balance"></textarea></label><label>Hands and grips<textarea name="hands" class="field" required maxlength="420" placeholder="Keep sleeve control; redirect lapel hand…"></textarea></label><label>Feet and body position<textarea name="feet" class="field" required maxlength="420" placeholder="Recover the reaping foot, turn…"></textarea></label><label>How to finish<input name="finish" class="field" required maxlength="400" placeholder="Complete the second attack when…"></label><label>Practice drill<input name="drill" class="field" maxlength="300" placeholder="5 controlled repetitions per side"></label><button class="primary full" type="submit" ${libs.length<2?'disabled':''}>Save my connection</button>${libs.length<2?'<p class="small muted">Add at least two techniques to My Library first.</p>':''}</form></details><div class="flow-sources-note"><strong>How suggestions work</strong><p>We provide technique links documented in judo teaching material and an educational interpretation of grip, footwork and timing. They are not automatically inferred by an AI, drawn from private app data, or ranked by measured competition frequency. Your saved favorites change which suggestions appear first.</p><button class="secondary" data-go="myLibrary">Edit My Library →</button></div>`}
function techByNameId(id){return allTechs.find(t=>t.id===id)}

function dueCards(){return D.vocabulary.filter(c=>(studyCategory==='All'||c.category===studyCategory)&&(!S.reviews[c.id]||Number(S.reviews[c.id].due)<=Date.now()))}
function review(){const cats=['All',...new Set(D.vocabulary.map(c=>c.category))],due=dueCards();let all=D.vocabulary.filter(c=>studyCategory==='All'||c.category===studyCategory),pool=due.length?due:all;if(!pool.length)return '<h1>No cards</h1>';if(!activeCard||!pool.some(x=>x.id===activeCard))activeCard=pool[0].id;let c=D.vocabulary.find(x=>x.id===activeCard);return `<span class="eyebrow">Practice Japanese</span><h1>Flashcards</h1><p class="sub">${due.length} due out of ${all.length} terms in this category. Reveal the meaning and rate your recall.</p><button class="chip ${audioMode?'active':''}" data-audio-mode aria-pressed="${audioMode}">◖)) Audio recognition ${audioMode?'on':'off'}</button><div class="filters">${cats.map(x=>`<button class="chip ${studyCategory===x?'active':''}" data-card-category="${attr(x)}">${h(x)}</button>`).join('')}</div><button class="flashcard" data-flip="1"><small>${h(c.category)}</small><strong>${flipped?h(c.back):audioMode?'Listen and recall the meaning':h(c.front)}</strong><span>${flipped?h(c.front):'Tap to reveal the English meaning'}</span></button><div class="phonetics flash-phonetics"><span class="kana">${audioMode&&!flipped?'?':h(T.kana(c.front))}</span>${speechButtons(c.front)}</div>${flipped?`<div class="grading"><button class="secondary" data-grade="1">Again</button><button class="secondary" data-grade="3">Hard</button><button class="primary" data-grade="4">Good</button><button class="primary" data-grade="5">Easy</button></div>`:'<p class="small muted">Cards you miss come back sooner. You can review them even when you’re offline.</p>'}${!due.length?'<p class="note small">All scheduled reviews are done. You can still keep practicing.</p>':''}`}
function grade(g){const prev=S.reviews[activeCard]||{reps:0,interval:0,ease:2.5};const ease=Math.max(1.3,prev.ease+(0.1-(5-g)*(0.08+(5-g)*0.02)));const reps=g<3?0:prev.reps+1;const days=g<3?0:g===3?1:reps===1?1:reps===2?6:Math.max(1,Math.round(prev.interval*ease));const minutes=g<3?2:0;S.reviews[activeCard]={reps,ease,interval:days,due:Date.now()+(minutes?minutes*60000:days*86400000),last:Date.now()};markActivity('flashcard',activeCard);save();activeCard=dueCards().find(c=>c.id!==activeCard)?.id||null;flipped=false;render()}
function getQuizPool(){const all=[...C.quizBank,...D.quizQuestions.map(q=>({...q,path:'shodan'})),...G.quizBank];const pool=quizScope==='All'?all:['vocab','techniques'].includes(quizScope)?all.filter(q=>q.kind===quizScope):all.filter(q=>q.path===quizScope||quizScope==='core'&&q.path==='start');const shuffled=[...pool];for(let i=shuffled.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[shuffled[i],shuffled[j]]=[shuffled[j],shuffled[i]]}return shuffled.slice(0,Math.min(10,shuffled.length))}
function beginQuiz(){quiz={items:getQuizPool(),index:0,score:0,selected:null};render()}
function quizScreen(){if(!quiz)return `<span class="eyebrow">Knowledge assessment</span><h1>Quiz center</h1><p class="sub">Choose an area, then answer up to ten questions. Includes vocabulary, official technique names, classifications and judo theory. Scores measure recall, not technical ability or rank eligibility.</p><div class="panel"><label>Study area<select id="quizScope" class="field"><option value="All" ${quizScope==='All'?'selected':''}>All judo</option><option value="vocab" ${quizScope==='vocab'?'selected':''}>Japanese vocabulary</option><option value="techniques" ${quizScope==='techniques'?'selected':''}>Technique recognition</option>${chapters.map(x=>`<option value="${x.key}" ${quizScope===x.key?'selected':''}>${h(x.label)}</option>`).join('')}</select></label><button class="primary full" data-start-quiz>Start quiz →</button></div>${S.quizHistory.length?`<div class="panel"><h2>Recent scores</h2>${S.quizHistory.slice(0,8).map(x=>`<div class="row between minirow"><span>${h(new Date(x.date).toLocaleDateString())}</span><strong>${Number(x.score)}/${Number(x.total)}</strong></div>`).join('')}</div>`:''}`;
if(quiz.index>=quiz.items.length)return `<span class="eyebrow">Quiz complete</span><h1>Your results</h1><div class="panel center"><div class="score">${quiz.score}/${quiz.items.length}</div><p>${p(quiz.score,quiz.items.length)}% correct</p><p class="muted">${quiz.score===quiz.items.length?'Strong recall. Try another topic.':'Review your missed terms, then give it another try.'}</p><div class="actions centered"><button class="primary" data-start-quiz>Try again</button><button class="secondary" data-reset-quiz>Choose topic</button></div></div>`;
const q=quiz.items[quiz.index];return `<span class="eyebrow">Question ${quiz.index+1} of ${quiz.items.length}</span><h1>Knowledge quiz</h1>${progressBar(quiz.index,quiz.items.length)}<div class="panel"><h2>${h(q.question)}</h2><div class="choices">${q.options.map(a=>`<button class="answer ${quiz.selected!==null?(a===q.answer?'correct':quiz.selected===a?'incorrect':''):''}" data-answer="${attr(a)}" ${quiz.selected!==null?'disabled':''}>${h(a)}</button>`).join('')}</div>${quiz.selected!==null?`<p class="note">${quiz.selected===q.answer?'Correct.':'Correct answer: '+h(q.answer)}</p><button class="primary full" data-next-quiz>${quiz.index===quiz.items.length-1?'Finish':'Next question →'}</button>`:''}</div>`}

function kata(){return `<span class="eyebrow">Kata reference</span><h1>Nage no Kata</h1><p class="sub">Five sets of three formal techniques. Study the attack, response, distance, uke/tori roles, order and etiquette under an instructor.</p>${D.kata.map((set,i)=>`<details><summary><span class="ordinal">${i+1}</span> ${h(set[0])}</summary><ol class="readable-list">${set.slice(1).map(name=>`<li>${h(name)} ${videoLink(name)}</li>`).join('')}</ol></details>`).join('')}<div class="panel"><h2>Go further</h2><p>Katame no Kata, Ju no Kata and other formal Kodokan kata offer a lifetime of study.</p>${link('https://learn.usjf.com/course-overview-nage-no-kata/','USJF Nage no Kata course')}</div>`}
function resources(){return `<span class="eyebrow">Official study links</span><h1>Resources</h1><p class="sub">Use recognized judo organizations for authoritative technique, safety, kata and rule information.</p>${C.resources.map(r=>`<div class="panel"><strong>${h(r.title)}</strong><p class="small muted">${h(r.type)}</p>${link(r.url,'Visit resource')}</div>`).join('')}<p class="note small">Officially classified techniques have direct Kodokan demonstration links; some additional variations use search links. Offline lessons work without internet, but external websites and videos require a connection.</p>`}
function rankKey(){return [S.profile?.organization||'Not sure',ageGroup,targetRank||'Shodan'].join('|')}
function ranksPage(){return home()}
function videosPage(){return `<div class="section-hero"><span class="eyebrow">Watch and study</span><h1>Kodokan video library</h1><p class="sub">Direct links to the Kodokan and IJF Academy’s 100 technique demonstration series. A video is not a substitute for an instructor.</p></div><div class="panel"><div class="row between"><strong>100 individual demonstration links</strong><span class="tag">Official channel</span></div><p class="small muted">Select a technique from the encyclopedia for its video and pronunciation. These highlights are a good place to begin.</p>${link(V.channel,'Visit the Kodokan channel')}</div>${V.extras.map(v=>`<a class="video-row" href="${attr(v.url)}" rel="noopener noreferrer" target="_blank"><span class="play-tile">▶</span><span><strong>${h(v.title)}</strong><small>${h(v.topic)} · YouTube ↗</small></span><span class="chev">›</span></a>`).join('')}<div class="panel"><button class="primary full" data-go="library">Browse all 100 techniques →</button></div>`;}
function more(){return `<span class="eyebrow">Study & settings</span><h1>More</h1>${[['review','字','Japanese flashcards','Practice vocabulary and pronunciation'],['quiz','✓','Quizzes','Check technique and theory knowledge'],['kata','道','Kata reference','Study the formal sequences'],['videos','▶','Kodokan videos','Official technique demonstrations'],['resources','↗','Official resources','Federation and Kodokan reference material'],['profile','人','Your rank profile','Set your rank, organization and goal'],['settings','⚙','Settings & backups','Export, import and offline help']].map(([id,icon,title,sub])=>`<button class="more-row" data-go="${id}"><span class="more-icon">${icon}</span><span><strong>${title}</strong><small>${sub}</small></span><span>›</span></button>`).join('')}`}

function profile(){const cur=P.canonical(S.profile?.rank||'White belt'),trg=P.validTarget(cur,S.profile?.targetRank)?P.canonical(S.profile.targetRank):P.defaults(cur,S.profile?.organization);return `<button class="ghost" data-go="home">← Home</button><span class="eyebrow">Your judo profile</span><h1>Rank & preferences</h1><form class="panel" id="profileForm"><label>Name (optional)<input class="field" name="name" maxlength="60" value="${attr(S.profile?.name||'')}"></label><label>Current rank<select class="field" name="rank">${rankChoices(cur,S.profile?.organization)}</select></label><label>Target rank<select class="field" name="targetRank">${rankChoices(trg,S.profile?.organization)}</select></label><label>Organization<select class="field" name="organization">${['Not sure','USJF','USA Judo','USJA','Kodokan','Other / local dojo'].map(v=>`<option ${S.profile?.organization===v?'selected':''} value="${attr(v)}">${h(v)}</option>`).join('')}</select></label><label>Age division<select class="field" name="ageGroup"><option value="adult" ${ageGroup==='adult'?'selected':''}>Adult / senior</option><option value="junior" ${ageGroup==='junior'?'selected':''}>Junior / youth</option></select></label><label>Learning pathway<select class="field" name="goal">${C.routes.map(r=>`<option value="${r.key}" ${S.journey===r.key?'selected':''}>${h(r.title)}</option>`).join('')}</select></label><button class="primary full" type="submit">Save preferences</button></form><p class="note">Your checked items are private study markers, not an official grading decision. Rank systems and requirements vary by dojo and age.</p>`}

function settings(){return `<span class="eyebrow">Data & installation</span><h1>Settings</h1><div class="panel"><h2>Your backup</h2><p class="small muted">Lessons, flashcards, rank checklists, saved techniques, custom combinations and preferences stay on this device. Archived journal or workout records from older versions remain only in backups; they are not displayed in the app.</p><div class="actions"><button class="primary" data-export>Export backup</button><button class="secondary" data-import>Restore backup</button></div><p class="tiny muted">Restore replaces all existing study data on this device after confirmation.</p></div><div class="panel"><h2>Japanese audio</h2><p class="small muted">Listen and Slow use your device’s speech voice, when available.</p></div><div class="panel"><h2>Offline and updates</h2><p class="small muted">Install through Safari → Share → Add to Home Screen. Core lessons can work offline after caching; YouTube links require internet. Back up before updating files on GitHub Pages.</p></div><div class="panel"><h2>Start fresh</h2><button class="secondary danger" data-reset>Erase local data</button></div>`}

function backup(){let blob=new Blob([JSON.stringify({app:'Judo Academy',version:7,exported:new Date().toISOString(),data:S},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='judo-academy-backup-'+today()+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function initEvents(){document.addEventListener('click',e=>{

 const builder=e.target.closest('[data-open-builder]');if(builder){const el=document.getElementById('customFlowBuilder');if(el){el.open=true;el.scrollIntoView({behavior:'smooth',block:'start'});}return;}
const rankHome=e.target.closest('[data-home-rank]');if(rankHome){const org=S.profile?.organization||'Not sure',key=[org,ageGroup,rankHome.dataset.homeRank].join('|');S.rankChecks[key]=S.rankChecks[key]||{};S.rankChecks[key][rankHome.dataset.homeRankIndex]=rankHome.checked;save();render();return;}
const addLib=e.target.closest('[data-library-add]');if(addLib){saveToLibrary(addLib.dataset.libraryAdd);return;}
 const starLib=e.target.closest('[data-library-star]');if(starLib){toggleFavorite(starLib.dataset.libraryStar);return;}
 const flowPin=e.target.closest('[data-flow-pin]');if(flowPin){const id=flowPin.dataset.flowPin;S.flowPinned=S.flowPinned.includes(id)?S.flowPinned.filter(x=>x!==id):[...S.flowPinned,id];save();render();return;}
 const flowRemove=e.target.closest('[data-flow-remove]');if(flowRemove){if(confirm('Delete this personal combination?')){S.customFlows=S.customFlows.filter(x=>x.id!==flowRemove.dataset.flowRemove);S.flowPinned=S.flowPinned.filter(x=>x!==flowRemove.dataset.flowRemove);selectedFlowEdge='';save();render();}return;}
 const flowRootButton=e.target.closest('[data-flow-root]');if(flowRootButton){S.flowPrefs.root=flowRootButton.dataset.flowRoot;detailId='';selectedFlowEdge='';save();render();return;}
 const flowNode=e.target.closest('[data-flow-node]');if(flowNode){S.flowPrefs.root=flowNode.dataset.flowNode;detailId='';selectedFlowEdge='';save();render();return;}
 const flowEdge=e.target.closest('[data-flow-edge]');if(flowEdge){selectedFlowEdge=flowEdge.dataset.flowEdge;render();document.querySelector('.flow-details')?.scrollIntoView({behavior:'smooth',block:'start'});return;}

const go=e.target.closest('[data-go]');if(go){navigate(go.dataset.go,go.dataset.id||'');return;}const browse=e.target.closest('[data-browse]');if(browse){const subject=browse.dataset.browse;const map={start:'first',core:'fundamentals',shodan:'blackbelt',competition:'sport',culture:'heritage'};navigate('journey',map[subject]);return;}const choice=e.target.closest('[data-filter]');if(choice){filter=choice.dataset.filter;render();return;}const cardcat=e.target.closest('[data-card-category]');if(cardcat){studyCategory=cardcat.dataset.cardCategory;activeCard=null;flipped=false;render();return;}if(e.target.closest('[data-flip]')){flipped=!flipped;render();return;}const speak=e.target.closest('[data-speak],[data-slow]');if(speak){const result=T.speak(speak.dataset.speak||speak.dataset.slow,!!speak.dataset.slow);if(!result.ok)alert(result.message);return;}
const rankChoice=e.target.closest('[data-target-rank]');if(rankChoice){targetRank=rankChoice.dataset.targetRank;render();return;}
if(e.target.closest('[data-audio-mode]')){audioMode=!audioMode;S.settings=S.settings||{};S.settings.audioMode=audioMode;save();render();return;}
const tab=e.target.closest('[data-lesson-tab]');if(tab){lessonStep=Number(tab.dataset.lessonTab);render();return;}
if(e.target.closest('[data-lesson-back]')){lessonStep=Math.max(0,lessonStep-1);render();return;}
const lnext=e.target.closest('[data-lesson-continue]');if(lnext){const id=lnext.dataset.lessonContinue;S.lessonSteps[id]=lessonChecklist(id).slice();S.lessonSteps[id][lessonStep]=true;markActivity('lesson-step',id);if(lessonStep<3){lessonStep++;}else{S.lessons[id]=true;markActivity('lesson',id)}save();render();return;}
const reflection=e.target.closest('[data-save-reflection]');if(reflection){S.reflections[reflection.dataset.saveReflection]=String(document.getElementById('lessonReflection')?.value||'').slice(0,1500);save();e.target.textContent='Saved ✓';return;}
const level=e.target.closest('[data-level]');if(level){const id=level.dataset.tech;S.skillLevels[id]=Math.max(0,Math.min(4,Number(level.dataset.level)));S.skills[id]=S.skillLevels[id]>0;markActivity('technique',id);save();render();return;}

const rating=e.target.closest('[data-grade]');if(rating){grade(+rating.dataset.grade);return;}if(e.target.closest('[data-start-quiz]')){beginQuiz();return;}if(e.target.closest('[data-reset-quiz]')){quiz=null;render();return;}const ans=e.target.closest('[data-answer]');if(ans&&quiz&&quiz.selected===null){quiz.selected=ans.dataset.answer;if(quiz.selected===quiz.items[quiz.index].answer)quiz.score++;render();return;}if(e.target.closest('[data-next-quiz]')&&quiz){quiz.index++;quiz.selected=null;if(quiz.index>=quiz.items.length){S.quizHistory.unshift({date:new Date().toISOString(),score:quiz.score,total:quiz.items.length});S.quizHistory=S.quizHistory.slice(0,50);save();}render();return;}if(e.target.closest('[data-export]')){backup();return;}if(e.target.closest('[data-import]')){document.getElementById('importFile').click();return;}if(e.target.closest('[data-reset]')){if(confirm('Erase all saved study data and profile, including archived older records? Export a backup first.')){S=fresh();save();navigate('welcome')}return;}const rankCheck=e.target.closest('[data-toggle-rank]');if(rankCheck){const key=rankKey();S.rankChecks[key]=S.rankChecks[key]||{};S.rankChecks[key][rankCheck.dataset.toggleRank]=rankCheck.checked;save();render();return;}
});

document.addEventListener('change',e=>{const box=e.target;
if(box.id==='homeCurrentRank'){S.profile.rank=box.value;if(!P.validTarget(box.value,S.profile.targetRank))S.profile.targetRank=P.defaults(box.value,S.profile.organization);save();render();return;}
if(box.id==='homeTargetRank'){S.profile.targetRank=box.value;save();render();return;}
if(box.id==='flowRoot'){S.flowPrefs.root=box.value;selectedFlowEdge='';detailId='';save();render();return;}
 if(box.id==='flowMode'){flowMode=box.value;S.flowPrefs.mode=flowMode;selectedFlowEdge='';save();render();return;}
 if(box.id==='flowStance'){flowStance=box.value;S.flowPrefs.stance=flowStance;save();render();return;}
 if(box.matches('[data-lesson]')){S.lessons[box.dataset.lesson]=box.checked;if(box.checked)markActivity('lesson',box.dataset.lesson);save();render();return;}if(box.matches('[data-skill]')){S.skills[box.dataset.skill]=box.checked;S.skillLevels[box.dataset.skill]=box.checked?Math.max(1,skillLevel(box.dataset.skill)):0;save();render();return;}if(box.id==='ageGroup'){ageGroup=box.value;render();return;}if(box.id==='rankTarget'){targetRank=box.value;render();return;}if(box.id==='quizScope'){quizScope=box.value;return;}});
document.addEventListener('input',e=>{if(e.target.id==='myTechSearch'){mySearch=e.target.value;const n=document.getElementById('myLibraryResults');if(n)n.innerHTML=myLibraryResults();return;}
 if(e.target.id==='techSearch'){search=e.target.value;document.getElementById('techResults').innerHTML=renderTechs()}});
document.addEventListener('submit',e=>{
if(e.target.id==='techNotesForm'){e.preventDefault();const id=e.target.dataset.id;if(S.techLibrary[id]){const form=new FormData(e.target);S.techLibrary[id].notes=String(form.get('notes')||'').slice(0,2200);S.techLibrary[id].tags=String(form.get('tags')||'').slice(0,160);save();render();}return;}
 if(e.target.id==='customFlowForm'){e.preventDefault();if(libraryOrder().length<2)return;const form=new FormData(e.target),from=String(form.get('from')||''),to=String(form.get('to')||'');if(from===to||!libraryOrder().some(t=>t.name===from)||!libraryOrder().some(t=>t.name===to)){alert('Choose two different saved techniques.');return;}const field=k=>String(form.get(k)||'').trim();for(const x of ['reaction','hands','feet','finish'])if(!field(x)){alert('Please describe the reaction, hands, feet, and finish.');return;}const id='personal-'+Date.now()+'-'+Math.random().toString(36).slice(2,7);const edge={id,from,to,kind:'Combination',reaction:field('reaction').slice(0,420),hands:field('hands').slice(0,420),feet:field('feet').slice(0,420),finish:field('finish').slice(0,400),drill:field('drill').slice(0,300)||'Practice safely with an instructor.',source:'personal',level:'Personal',personal:true};S.customFlows.push(edge);S.flowPrefs.root=from;S.flowPinned.push(id);flowMode='all';S.flowPrefs.mode='all';selectedFlowEdge=id;save();render();return;}
 
if(e.target.id==='profileForm'){e.preventDefault();const form=new FormData(e.target),rank=String(form.get('rank')||'White belt'),organization=String(form.get('organization')||'Not sure'),name=String(form.get('name')||'').slice(0,60),goal=String(form.get('goal')||'first'),division=String(form.get('ageGroup')||'adult'),desired=String(form.get('targetRank')||'');const targetRank=P.validTarget(rank,desired)?desired:P.defaults(rank,organization);ageGroup=division==='junior'?'junior':'adult';S.profile={...S.profile,rank,organization,name,goal,targetRank,ageGroup};S.journey=journeyByKey(goal).key;save();navigate('home');return;}});
document.getElementById('importFile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>8*1024*1024)throw new Error('Backup too large');const obj=JSON.parse(await file.text()),a=obj.data;if(!a||typeof a.lessons!=='object'||typeof a.skills!=='object'||typeof a.reviews!=='object'||!Array.isArray(a.journal)||!['Judo Academy','Judo Shodan Academy'].includes(obj.app))throw new Error('This is not a supported Judo Academy backup');if(confirm('Replace the progress on this device with the contents of the backup?')){S={...fresh(),...a};if(!S.rankChecks||typeof S.rankChecks!=='object')S.rankChecks={};if(!S.skillLevels||typeof S.skillLevels!=='object')S.skillLevels={};if(!S.lessonSteps||typeof S.lessonSteps!=='object')S.lessonSteps={};if(!S.reflections||typeof S.reflections!=='object')S.reflections={};if(!Array.isArray(S.activityLog))S.activityLog=[];if(!Array.isArray(S.exerciseLog))S.exerciseLog=[];if(!S.exercisePrefs||typeof S.exercisePrefs!=='object')S.exercisePrefs={};if(!S.techLibrary||typeof S.techLibrary!=='object')S.techLibrary={};if(!Array.isArray(S.flowPinned))S.flowPinned=[];if(!Array.isArray(S.customFlows))S.customFlows=[];if(!Array.isArray(S.flowHistory))S.flowHistory=[];if(!S.flowPrefs||typeof S.flowPrefs!=='object')S.flowPrefs={};if(!S.profile)S.profile={rank:'Ikkyu',organization:'USJF',name:'',goal:'blackbelt'};ageGroup=S.profile.ageGroup==='junior'?'junior':'adult';save();navigate('home')}}catch(err){alert('Import failed: '+err.message)}e.target.value='';});}
initEvents();if('serviceWorker'in navigator&&location.protocol!=='file:')window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(console.warn));render();
